import { ArrowDownRight, ArrowUpRight, Minus } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import type { Metric } from "@/types/domain";
export function MetricCard({ metric }: { metric: Metric }) { const Icon = metric.trend === "up" ? ArrowUpRight : metric.trend === "down" ? ArrowDownRight : Minus; return <Card><CardContent className="p-5"><p className="text-sm text-muted-foreground">{metric.label}</p><div className="mt-2 flex items-end justify-between gap-2"><strong className="text-2xl tracking-tight">{metric.value}</strong>{metric.change && <span className="inline-flex items-center text-xs text-muted-foreground"><Icon className="mr-1 size-3.5" />{metric.change}</span>}</div></CardContent></Card>; }
